	'messages:missing-revision-permission' => 'ro:Revizia #$1 aparține unei pagini șterse. Puteți [{{fullurl:{{#Special:Undelete}}|target=$3&timestamp=$2&diff=prev}} s-o vedeți]; detalii pot fi găsite în  [{{fullurl:{{#Special:Log}}/delete|page=$3}} jurnalul de ștergeri].',
	'messages:missing-revision' => 'ro:Versiunea nr. $1 a paginii „{{FULLPAGENAME}}” nu există.

